/// The shared fixture generated by the tokens build, read from the repository so the values are
/// never copied by hand.
private enum BrandFixture {
    struct Entry: Sendable {
        let name: String
        let light: UInt32
        let dark: UInt32
        let accent: (light: UInt32, dark: UInt32)?
        let ink: [Int: UInt32]
        let themes: [String: [String: StanceBrandEngine.Role]]
        let contrastFailures: Int

        var brand: StanceBrand {
            StanceBrand(
                name: name,
                light: StanceRGBA(hex: light),
                dark: StanceRGBA(hex: dark),
                accent: accent.map { StanceRGBA(hex: $0.light) },
                accentDark: accent.map { StanceRGBA(hex: $0.dark) }
            )
        }
    }

    static let url = URL(fileURLWithPath: #filePath)
        .deletingLastPathComponent() // StanceUITests
        .deletingLastPathComponent() // Tests
        .deletingLastPathComponent() // ios
        .deletingLastPathComponent() // platforms
        .deletingLastPathComponent() // repository root
        .appendingPathComponent("packages/tokens/generated/json/brand-fixture.json")

    static func load() throws -> [Entry] {
        let data = try Data(contentsOf: url)
        let root = try #require(try JSONSerialization.jsonObject(with: data) as? [String: Any])
        let brands = try #require(root["brands"] as? [[String: Any]])
        func hex(_ value: Any?) throws -> UInt32 {
            let text = try #require(value as? String)
            return try #require(StanceBrandEngine.parseHex(text))
        }
        return try brands.map { entry in
            let brand = try #require(entry["brand"] as? [String: Any])
            let accent: (light: UInt32, dark: UInt32)? = try {
                switch brand["accent"] {
                case nil: return nil
                case let single as String:
                    let c = try hex(single)
                    return (c, c)
                case let pair as [String: Any]:
                    return (try hex(pair["light"]), try hex(pair["dark"]))
                default:
                    Issue.record("Unexpected accent")
                    return nil
                }
            }()
            let ink = try #require(entry["ink"] as? [String: String])
            let themes = try #require(entry["themes"] as? [String: [String: [String: Any]]])
            return Entry(
                name: try #require(brand["name"] as? String),
                light: try hex(brand["light"]),
                dark: try hex(brand["dark"]),
                accent: accent,
                ink: Dictionary(uniqueKeysWithValues: try ink.map { (try #require(Int($0.key)), try hex($0.value)) }),
                themes: try themes.mapValues { roles in
                    try roles.mapValues { role in
                        StanceBrandEngine.Role(
                            hex: try hex(role["hex"]),
                            alpha: try #require((role["alpha"] as? NSNumber)?.doubleValue)
                        )
                    }
                },
                contrastFailures: (entry["contrastFailures"] as? [Any])?.count ?? -1
            )
        }
    }
}

@Suite("Brand engine")
struct BrandEngineTests {
    @Test("Every role of every brand and theme matches the shared fixture exactly")
    func fixture() throws {
        let entries = try BrandFixture.load()
        #expect(entries.map(\.name) == ["Binds", "Harbour", "Sage", "Graphite"])
        var checked = 0
        for entry in entries {
            let resolved = StanceBrandEngine.resolve(light: entry.light, dark: entry.dark, accent: entry.accent)
            #expect(resolved.ink == entry.ink, "\(entry.name) ink scale")
            #expect(Set(resolved.themes.keys) == ["light", "dark", "high-contrast"])
            for theme in StanceBrandRecipe.allThemes {
                let expected = try #require(entry.themes[theme.name])
                let actual = try #require(resolved.themes[theme.name])
                #expect(expected.count == theme.roles.count)
                for role in theme.roles.map(\.role) {
                    let want = try #require(expected[role], "\(entry.name) \(theme.name) \(role) missing in fixture")
                    let got = try #require(actual[role])
                    #expect(
                        got == want,
                        "\(entry.name) \(theme.name) \(role): \(StanceBrandEngine.hexString(got.hex)) \(got.alpha), fixture \(StanceBrandEngine.hexString(want.hex)) \(want.alpha)"
                    )
                    checked += 1
                }
            }
            #expect(entry.contrastFailures == 0)
            #expect(StanceResolvedBrand(entry.brand).report.isEmpty, "\(entry.name) contrast")
        }
        // Four brands, three themes, every role of StanceColorTokens.
        #expect(checked == 4 * 3 * StanceBrandRecipe.light.roles.count)
        #expect(checked == 720)
    }

    @Test("Public colours for a brand are the fixture's resolved roles")
    func publicColors() throws {
        for entry in try BrandFixture.load() where entry.name != "Binds" {
            let brand = entry.brand
            #expect(!brand.isDefaultPalette)
            for mode in StanceTheme.Mode.allCases {
                let roles = try #require(entry.themes[mode.rawValue])
                let expected = StanceColorTokens { roles[$0]!.rgba }
                #expect(brand.colors(for: mode) == expected)
                #expect(StanceTheme(mode: mode, brand: brand).colors.tokens == expected)
            }
        }
    }

    @Test("Hex strings parse like the web engine")
    func hexParsing() {
        #expect(StanceBrandEngine.parseHex("#FCF6EB") == 0xFCF6EB)
        #expect(StanceBrandEngine.parseHex("fcf6eb") == 0xFCF6EB)
        #expect(StanceBrandEngine.parseHex("#abc") == 0xAABBCC)
        #expect(StanceBrandEngine.parseHex("#FCF6EB80") == 0xFCF6EB)
        #expect(StanceBrandEngine.parseHex("#GGGGGG") == nil)
        #expect(StanceBrandEngine.parseHex("#12345") == nil)
        #expect(StanceBrand(name: "Bad", light: "ivory", dark: "#000") == nil)
        #expect(StanceBrand(name: "Bad", light: "#fff", dark: "#000", accent: "nope") == nil)
        let sage = StanceBrand(name: "Sage", light: "#F4F2EC", dark: "#171D1A", accent: "#5E7361", accentDark: "#8FA892")
        #expect(sage?.accent == .themed(light: StanceRGBA(hex: 0x5E7361), dark: StanceRGBA(hex: 0x8FA892)))
        #expect(sage?.lightHex == "#F4F2EC")
        #expect(sage?.darkHex == "#171D1A")
        #expect(StanceBrandEngine.hexString(0x00000A) == "#00000A")
    }

    @Test("Rounding is half up, as JavaScript Math.round")
    func rounding() {
        #expect(StanceBrandEngine.roundHalfUp(2.5) == 3)
        #expect(StanceBrandEngine.roundHalfUp(2.4999) == 2)
        #expect(StanceBrandEngine.roundHalfUp(0) == 0)
        #expect(StanceBrandEngine.byte(255.6) == 255)
        #expect(StanceBrandEngine.byte(-3) == 0)
    }

    @Test("Binds through the engine reproduces the published tokens")
    func bindsMatchesTokens() {
        let resolved = StanceBrand.binds.resolve()
        let published: [String: StanceColorTokens] = [
            "light": StanceTokens.light.colors,
            "dark": StanceTokens.dark.colors,
            "high-contrast": StanceTokens.highContrast.colors,
        ]
        for theme in StanceBrandRecipe.allThemes {
            let roles = resolved.themes[theme.name] ?? [:]
            let engine = StanceColorTokens { roles[$0]!.rgba }
            let tokens = published[theme.name]!
            for entry in theme.roles {
                let keyPath = Self.keyPath(entry.property)
                let got = engine[keyPath: keyPath]
                let want = tokens[keyPath: keyPath]
                if case .derive = entry.recipe {
                    // The spec allows 1/255 per channel for roles that became derivations.
                    let step = 1.0 / 255 + 1e-9
                    #expect(abs(got.red - want.red) <= step && abs(got.green - want.green) <= step
                        && abs(got.blue - want.blue) <= step && got.alpha == want.alpha,
                        "\(theme.name) \(entry.role)")
                } else {
                    #expect(got == want, "\(theme.name) \(entry.role)")
                }
            }
        }
        // The default palette itself is the generated tokens, unchanged.
        for mode in StanceTheme.Mode.allCases {
            #expect(StanceBrand.binds.colors(for: mode) == StanceTheme.defaultTokens(for: mode).colors)
            #expect(StanceTheme(mode: mode, brand: .binds) == StanceTheme(mode: mode))
        }
        #expect(StanceBrand.binds.isDefaultPalette)
        #expect(StanceBrand.binds.contrastReport().isEmpty)
        #expect(StanceBrand(name: "Ours", light: "#FCF6EB", dark: "#140C2E")!.isDefaultPalette)
    }

    @Test("Hard accents are fitted with no contrast failures",
          arguments: ["#7A7A7A", "#FFFF00", "#000000", "#FFFFFF"])
    func edgeAccents(accent: String) throws {
        let pairs: [(String, String)] = [("#FCF6EB", "#140C2E"), ("#F2F8FF", "#0A1A50"), ("#FAFAF7", "#1A1A1F"), ("#FFFFFF", "#000000")]
        for (light, dark) in pairs {
            let brand = try #require(StanceBrand(name: "Edge", light: light, dark: dark, accent: accent))
            #expect(brand.contrastReport().isEmpty, "\(accent) on \(light) and \(dark): \(brand.contrastReport())")
            let themed = try #require(StanceBrand(name: "Edge", light: light, dark: dark, accent: accent, accentDark: accent))
            #expect(themed.contrastReport().isEmpty)
        }
    }

    @Test("The contrast report flags a poor pair")
    func poorPair() throws {
        let brand = try #require(StanceBrand(name: "Washed out", light: "#FFFFFF", dark: "#C8C8C8"))
        let report = brand.contrastReport()
        #expect(!report.isEmpty)
        let failure = try #require(report.first { $0.foreground == "fg-default" && $0.background == "bg-canvas" && $0.mode == .light })
        #expect(failure.required == 4.5)
        #expect(failure.ratio < 4.5)
        #expect(failure.description.hasPrefix("light: fg-default on bg-canvas is "))
        #expect(report.contains { $0.mode == .highContrast && $0.required == 7 })
    }

    @Test("Brands are cached and compare by value")
    func caching() throws {
        let a = try #require(StanceBrand(name: "Harbour", light: "#F2F8FF", dark: "#0A1A50", accent: "#FF5A36"))
        let b = try #require(StanceBrand(name: "Harbour", light: "#f2f8ff", dark: "#0a1a50", accent: "#ff5a36"))
        #expect(a == b)
        #expect(StanceBrandCache.shared.resolved(a).light == StanceBrandCache.shared.resolved(b).light)
        let fromColor = StanceBrand(name: "Harbour", light: Color(StanceRGBA(hex: 0xF2F8FF)), dark: Color(StanceRGBA(hex: 0x0A1A50)), accent: Color(StanceRGBA(hex: 0xFF5A36)))
        #expect(fromColor == a)
    }

    static func keyPath(_ property: String) -> KeyPath<StanceColorTokens, StanceRGBA> {
        let all: [String: KeyPath<StanceColorTokens, StanceRGBA>] = [
            "bgCanvas": \.bgCanvas, "bgSubtle": \.bgSubtle, "bgMuted": \.bgMuted, "bgEmphasis": \.bgEmphasis,
            "bgSurface": \.bgSurface, "bgSurfaceRaised": \.bgSurfaceRaised, "bgOverlay": \.bgOverlay,
            "bgInverse": \.bgInverse, "bgScrim": \.bgScrim, "fgDefault": \.fgDefault, "fgMuted": \.fgMuted,
            "fgSubtle": \.fgSubtle, "fgDisabled": \.fgDisabled, "fgInverse": \.fgInverse, "fgLink": \.fgLink,
            "borderSubtle": \.borderSubtle, "borderDefault": \.borderDefault, "borderStrong": \.borderStrong,
            "borderControl": \.borderControl, "borderControlHover": \.borderControlHover, "separator": \.separator,
            "accentBg": \.accentBg, "accentBgHover": \.accentBgHover, "accentBgActive": \.accentBgActive,
            "accentFg": \.accentFg, "interactiveHover": \.interactiveHover, "interactiveActive": \.interactiveActive,
            "interactiveSelected": \.interactiveSelected, "interactiveSelectedFg": \.interactiveSelectedFg,
            "focusRing": \.focusRing, "focusRingOffset": \.focusRingOffset, "disabledBg": \.disabledBg,
            "disabledFg": \.disabledFg, "disabledBorder": \.disabledBorder, "dangerFg": \.dangerFg,
            "dangerBg": \.dangerBg, "dangerBorder": \.dangerBorder, "dangerSolid": \.dangerSolid,
            "dangerSolidHover": \.dangerSolidHover, "dangerOnSolid": \.dangerOnSolid, "successFg": \.successFg,
            "successBg": \.successBg, "successBorder": \.successBorder, "successSolid": \.successSolid,
            "successOnSolid": \.successOnSolid, "warningFg": \.warningFg, "warningBg": \.warningBg,
            "warningBorder": \.warningBorder, "warningSolid": \.warningSolid, "warningOnSolid": \.warningOnSolid,
            "infoFg": \.infoFg, "infoBg": \.infoBg, "infoBorder": \.infoBorder, "infoSolid": \.infoSolid,
            "infoOnSolid": \.infoOnSolid, "chart1": \.chart1, "chart2": \.chart2, "chart3": \.chart3,
            "chart4": \.chart4, "chart5": \.chart5,
        ]
        guard let keyPath = all[property] else { preconditionFailure("No key path for \(property)") }
        return keyPath
    }
}

@Suite("Brand in the environment")
@MainActor
struct BrandEnvironmentTests {
    final class Box {
        var theme: StanceTheme?
        var brand: StanceBrand?
    }

    struct Probe: View {
        let box: Box
        @Environment(\.stanceTheme) private var theme
        @Environment(\.stanceBrand) private var brand

        var body: some View {
            box.theme = theme
            box.brand = brand
            return Color.clear.frame(width: 4, height: 4)
        }
    }

    static let harbour = StanceBrand(name: "Harbour", light: "#F2F8FF", dark: "#0A1A50", accent: "#FF5A36")!

    @discardableResult
    func render<V: View>(_ view: V) -> CGImage? {
        let renderer = ImageRenderer(content: view)
        return renderer.cgImage
    }

    @Test("A brand applies to its subtree only")
    func scoping() {
        let outside = Box()
        let inside = Box()
        render(VStack {
            Probe(box: outside)
            Probe(box: inside).stanceBrand(Self.harbour)
        }
        .environment(\.stanceTheme, .dark))
        #expect(outside.theme == .dark)
        #expect(outside.brand == .binds)
        #expect(inside.brand == Self.harbour)
        #expect(inside.theme?.mode == .dark)
        #expect(inside.theme?.brand == Self.harbour)
        #expect(inside.theme?.colors.tokens == Self.harbour.colors(for: .dark))
        #expect(inside.theme?.colors.tokens != StanceTokens.dark.colors)
    }

    @Test("Providers apply and inherit brands in every appearance",
          arguments: [StanceAppearance.light, .dark, .highContrast])
    func provider(appearance: StanceAppearance) {
        let mode = appearance.resolve(colorScheme: .light, increasedContrast: false)
        let direct = Box()
        render(Probe(box: direct).stanceTheme(appearance, brand: Self.harbour))
        #expect(direct.theme == StanceTheme(mode: mode, brand: Self.harbour))

        let inherited = Box()
        render(Probe(box: inherited).stanceTheme(appearance).stanceBrand(Self.harbour))
        #expect(inherited.theme == StanceTheme(mode: mode, brand: Self.harbour))

        let scoped = Box()
        render(Probe(box: scoped).stanceScopedTheme(mode).stanceBrand(Self.harbour))
        #expect(scoped.theme?.colors.tokens == Self.harbour.colors(for: mode))

        let plain = Box()
        render(Probe(box: plain).stanceTheme(appearance))
        #expect(plain.theme == StanceTheme(mode: mode))
    }

    @Test("System appearance with Increase Contrast uses the brand's high contrast theme")
    func increasedContrast() {
        let box = Box()
        render(Probe(box: box)
            .stanceTheme(.system, brand: Self.harbour)
            .environment(\._colorSchemeContrast, .increased))
        #expect(box.theme?.mode == .highContrast)
        #expect(box.theme?.colors.tokens == Self.harbour.colors(for: .highContrast))
    }

    struct Sample: View {
        @State private var on = true
        var body: some View {
            VStack(alignment: .leading, spacing: StanceSpacing.lg) {
                StanceButton("Deploy", leadingIcon: .send) {}
                StanceButton("Preview", variant: .outline) {}
                Toggle("Auto-deploy", isOn: $on).toggleStyle(.stance)
                StanceCheckbox("Apply to new members", isOn: $on)
                StanceBadge("Live", tone: .success)
                StanceInlineAlert("Relay offline", message: "Deployments resume soon.", tone: .warning)
                StanceProgressView("Mailboxes updated", value: 0.72)
            }
            .padding()
            .frame(width: 390)
        }
    }

    @Test("Components render with a custom brand in every theme", arguments: StanceTheme.Mode.allCases)
    func rendersBranded(mode: StanceTheme.Mode) throws {
        let theme = StanceTheme(mode: mode, brand: Self.harbour)
        let image = try #require(render(Sample()
            .environment(\.stanceTheme, theme)
            .environment(\.stanceBrand, Self.harbour)
            .background(theme.colors.bgCanvas)))
        #expect(image.width > 0 && image.height > 100)
    }

    #if canImport(UIKit)
    @Test("UIKit lookups honour a brand")
    func uikit() {
        let brand = Self.harbour
        for mode in StanceTheme.Mode.allCases {
            #expect(StanceUIKit.color(\.accentBg, in: mode, brand: brand) == UIColor(brand.colors(for: mode).accentBg))
        }
        let dynamic = StanceUIKit.color(\.accentBg, brand: brand)
        let dark = dynamic.resolvedColor(with: UITraitCollection(userInterfaceStyle: .dark))
        #expect(dark == UIColor(brand.colors(for: .dark).accentBg))
        let contrast = dynamic.resolvedColor(with: UITraitCollection(accessibilityContrast: .high))
        #expect(contrast == UIColor(brand.colors(for: .highContrast).accentBg))
        #expect(StanceUIKit.color(\.bgCanvas, in: .light) == UIColor(StanceTokens.light.colors.bgCanvas))
    }
    #endif
}
